using System;using System.IO;using System.Linq;using System.Reflection;using System.Threading.Tasks;using UnityEngine;using UnityEditor;using UnityEngine.SceneManagement;using Object=UnityEngine.Object;
public static class CheckInterceptorHarborLights
{
    static async Task Frames(int n){for(int i=0;i<n;i++){EditorApplication.Step();await Task.Delay(30);}}
    static void Require(bool value,string message){if(!value)throw new Exception(message);}
    static void Capture(Camera camera,string file){var prev=RenderTexture.active;var target=camera.targetTexture;var rt=new RenderTexture(1600,900,24){antiAliasing=4};Texture2D tex=null;try{camera.targetTexture=rt;camera.Render();RenderTexture.active=rt;tex=new Texture2D(1600,900,TextureFormat.RGB24,false);tex.ReadPixels(new Rect(0,0,1600,900),0,0);tex.Apply();File.WriteAllBytes(file,tex.EncodeToPNG());}finally{camera.targetTexture=target;RenderTexture.active=prev;if(tex)UnityEngine.Object.DestroyImmediate(tex);rt.Release();UnityEngine.Object.DestroyImmediate(rt);}}
    static async Task<string> Check(string scene,TestDriveSelection.CourseKind course,bool night,bool expectSpill,bool capture)
    {
        TestDriveSelection.Select(4,lighting:night?TestDriveSelection.TimeOfDay.Night:TestDriveSelection.TimeOfDay.Day,course:course,vehicleName:"INTERCEPTOR");SceneManager.LoadScene(scene);await Frames(5);Object.FindAnyObjectByType<TestDriveIntro>()?.Skip();await Frames(12);
        var car=Object.FindAnyObjectByType<TestDriveMovement>();var roof=Object.FindAnyObjectByType<InterceptorRoofLights>();Require(car&&roof&&roof.GetComponentInParent<TestDriveMovement>()==car,"No Interceptor beacon controller");var so=new SerializedObject(roof);var red=(Light)so.FindProperty("redSpill").objectReferenceValue;var blue=(Light)so.FindProperty("blueSpill").objectReferenceValue;var lenses=(Renderer)so.FindProperty("lenses").objectReferenceValue;Require(red&&blue&&lenses,"Beacon setup missing");
        var body=car.GetComponent<Rigidbody>();body.linearVelocity=Vector3.zero;body.angularVelocity=Vector3.zero;body.constraints=RigidbodyConstraints.FreezeAll;await Frames(12);
        var lamps=Object.FindObjectsByType<Light>(FindObjectsInactive.Include).Where(l=>l.enabled&&!l.transform.IsChildOf(car.transform)&&l.type!=LightType.Directional).Take(12).ToArray();var baseline=lamps.Select(l=>l.intensity).ToArray();
        bool bright=false,dim=false,spillOn=false;int start=Time.frameCount;var block=new MaterialPropertyBlock();
        for(int i=0;i<60;i++){await Frames(1);lenses.GetPropertyBlock(block,0);float emission=block.GetColor("_EmissionColor").maxColorComponent;bright|=emission>1;dim|=emission<.2f;Require(red.enabled==blue.enabled,"Beacon spills out of sync");spillOn|=red.enabled;if(!expectSpill)Require(!red.enabled&&!blue.enabled,"Harbor beacon spill active");}
        Require(Time.frameCount>start&&bright&&dim,"Roof beacon lenses did not flash");Require(spillOn==expectSpill,"Unexpected beacon spill behavior in "+scene);if(scene=="HarborStreetScene"&&night){Require(lamps.Length>0,"No environmental lights enabled");for(int i=0;i<lamps.Length;i++)Require(Mathf.Abs(lamps[i].intensity-baseline[i])<.05f,"Environmental light intensity changed while stationary");}
        if(capture){var folder="/Users/yoshi/Documents/ChatGPT/Unity Project/Artifacts/HarborStreet/InterceptorLights";Directory.CreateDirectory(folder);var startField=typeof(InterceptorRoofLights).GetField("startedAt",BindingFlags.NonPublic|BindingFlags.Instance);var update=typeof(InterceptorRoofLights).GetMethod("Update",BindingFlags.NonPublic|BindingFlags.Instance);startField.SetValue(roof,Time.time-.2f);update.Invoke(roof,null);Capture(Camera.main,folder+"/after-off.png");startField.SetValue(roof,Time.time-.05f);update.Invoke(roof,null);Capture(Camera.main,folder+"/after-on.png");}
        return scene+" "+(night?"night":"day")+": lenses flash, spill "+(spillOn?"flashes":"off")+", environmental samples="+lamps.Length+", frames="+start+" -> "+Time.frameCount;
    }
    public static async Task<string> Run(){try{var a=await Check("HarborStreetScene",TestDriveSelection.CourseKind.HarborStreet,true,false,true);var b=await Check("HarborStreetScene",TestDriveSelection.CourseKind.HarborStreet,false,false,false);var c=await Check("MountainPassScene",TestDriveSelection.CourseKind.MountainPass,true,true,false);var d=await Check("TestTrackScene",TestDriveSelection.CourseKind.TestCircuit,true,true,false);return string.Join("; ",a,b,c,d);}finally{Time.timeScale=1;SceneManager.LoadScene("ShowcaseScene");await Frames(3);}}
}
